class Conv2d: Module {
    let weight: MLXArray
    let bias: MLXArray?
    let stride: (Int, Int)
    let padding: (Int, Int)

    init(
        inChannels: Int,
        outChannels: Int,
        kernelSize: (Int, Int),
        stride: (Int, Int) = (1, 1),
        padding: (Int, Int) = (0, 0),
        bias: Bool = true
    ) {
        self.weight = MLXArray.random(
            -0.1 ..< 0.1,
            [outChannels, inChannels, kernelSize.0, kernelSize.1]
        )
        if bias {
            self.bias = MLXArray.zeros([outChannels])
        } else {
            self.bias = nil
        }
        self.stride = stride
        self.padding = padding
    }

    override func callAsFunction(_ x: MLXArray) -> MLXArray {
        // Convolution operation
        var output = conv2d(x, weight, stride: stride, padding: padding)
        if let bias = bias {
            output = output + bias.reshaped([1, -1, 1, 1])
        }
        return output
    }
}
```

