func cosineSimilarity(_ a: MLXArray, _ b: MLXArray) -> Float {
    let dotProduct = (a * b).sum()
    let normA = sqrt((a * a).sum())
    let normB = sqrt((b * b).sum())
    return (dotProduct / (normA * normB)).item()
}

