func scaledDotProductAttention(
    query: MLXArray,
    key: MLXArray,
    value: MLXArray,
    mask: MLXArray? = nil
) -> MLXArray {
    let dk = Float(query.shape[-1])
    var scores = matmul(query, key.transposed(axes: [0, 1, 3, 2])) / sqrt(dk)

    if let mask = mask {
        scores = scores + mask
    }

    let attention = softmax(scores, axis: -1)
    return matmul(attention, value)
}
```

